package com.aistudio.iossideloadbridge.app.anisette

import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

/**
 * Anisette headers required by Apple's GSA (Grand Slam Authentication) servers.
 * These headers spoof Apple device attestation (typically generated by macOS AuthKit/akd).
 */
data class AnisetteHeaders(
    val serverUsed: String,
    val clientTime: String,
    val md: String,
    val mdM: String,
    val mdRinfo: String,
    val mdLu: String,
    val srlNo: String,
    val clientInfo: String,
    val timeZone: String,
    val locale: String,
    val deviceId: String,
    val implementationVersion: String? = null
) {
    /**
     * Routing info as numeric integer value, matching AltSign's uint64_t routingInfo.
     */
    val routingInfo: Long
        get() = mdRinfo.toLongOrNull() ?: 17106176L

    /**
     * Converts to the exact HTTP header map expected by Apple GSA auth endpoints
     * (e.g. gsa.apple.com / auth.apple.com).
     */
    fun toHeaderMap(): Map<String, String> = mapOf(
        "X-Apple-I-Client-Time" to clientTime,
        "X-Apple-I-MD" to md,
        "X-Apple-I-MD-M" to mdM,
        "X-Apple-I-MD-RINFO" to mdRinfo,
        "X-Apple-I-MD-LU" to mdLu,
        "X-Apple-I-SRL-NO" to srlNo,
        "X-MMe-Client-Info" to clientInfo,
        "X-Apple-I-TimeZone" to timeZone,
        "X-Apple-Locale" to locale,
        "X-Mme-Device-Id" to deviceId
    )

    /**
     * Converts to the anisette entries for Apple GSA 'cpd' dictionary matching AltSign's clientDictionary:
     * - X-Apple-I-MD-RINFO is an integer (<integer>), not a string
     * - X-MMe-Client-Info is excluded (sent only as HTTP header)
     */
    fun toCpdMap(): Map<String, Any> = mapOf(
        "X-Apple-I-Client-Time" to clientTime,
        "X-Apple-Locale" to locale,
        "X-Apple-I-TimeZone" to timeZone,
        "X-Apple-I-MD" to md,
        "X-Apple-I-MD-LU" to mdLu,
        "X-Apple-I-MD-M" to mdM,
        "X-Apple-I-MD-RINFO" to routingInfo,
        "X-Mme-Device-Id" to deviceId,
        "X-Apple-I-SRL-NO" to srlNo
    )
}

data class ServerCheckResult(
    val serverUrl: String,
    val isReachable: Boolean,
    val statusCode: Int = 0,
    val responseTimeMs: Long = 0L,
    val implementationVersion: String? = null,
    val errorMessage: String? = null,
    val headers: AnisetteHeaders? = null
)

class AnisetteClient(
    private val timeoutSeconds: Long = 5L
) {
    companion object {
        private const val TAG = "AnisetteClient"

        /**
         * Known official and community SideStore/AltServer anisette servers
         * arranged in priority order for the fallback chain.
         */
        val OFFICIAL_SERVERS = listOf(
            "https://ani.sidestore.io",
            "https://ani.sidestore.app",
            "https://ani.846969.xyz",
            "https://ani.npeg.us",
            "https://anisette.wedotstud.io"
        )
    }

    private val httpClient: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(timeoutSeconds, TimeUnit.SECONDS)
        .readTimeout(timeoutSeconds, TimeUnit.SECONDS)
        .writeTimeout(timeoutSeconds, TimeUnit.SECONDS)
        .followRedirects(true)
        .build()

    /**
     * Fetches fresh Anisette headers by querying the anisette servers in a fallback chain.
     *
     * @param preferredServer Optional specific server URL to prioritize before falling back
     * @return Result containing [AnisetteHeaders] or failure with aggregated error details
     */
    suspend fun fetchAnisetteHeaders(preferredServer: String? = null): Result<AnisetteHeaders> =
        withContext(Dispatchers.IO) {
            val serversToTry = buildList {
                if (!preferredServer.isNullOrBlank() && preferredServer !in OFFICIAL_SERVERS) {
                    add(preferredServer.trimEnd('/'))
                }
                if (!preferredServer.isNullOrBlank() && preferredServer in OFFICIAL_SERVERS) {
                    add(preferredServer.trimEnd('/'))
                }
                OFFICIAL_SERVERS.forEach {
                    val normalized = it.trimEnd('/')
                    if (normalized !in this) {
                        add(normalized)
                    }
                }
            }

            val errorLog = mutableListOf<String>()

            for (server in serversToTry) {
                Log.i(TAG, "Attempting Anisette fetch from $server...")
                val startTime = System.currentTimeMillis()
                try {
                    val request = Request.Builder()
                        .url("$server/")
                        .header("Accept", "application/json")
                        .header("User-Agent", "iOS-Sideload-Bridge-Android/1.0")
                        .get()
                        .build()

                    httpClient.newCall(request).execute().use { response ->
                        val duration = System.currentTimeMillis() - startTime
                        val implVersion = response.header("Implementation-Version")

                        if (!response.isSuccessful) {
                            val msg = "$server returned HTTP ${response.code} in ${duration}ms"
                            Log.w(TAG, msg)
                            errorLog.add(msg)
                            return@use
                        }

                        val body = response.body?.string()
                        if (body.isNullOrBlank()) {
                            val msg = "$server returned empty body in ${duration}ms"
                            Log.w(TAG, msg)
                            errorLog.add(msg)
                            return@use
                        }

                        val json = JSONObject(body)

                        // Validate that essential OTP headers exist
                        if (!json.has("X-Apple-I-MD") || !json.has("X-Apple-I-MD-M")) {
                            val msg = "$server returned JSON missing X-Apple-I-MD/X-Apple-I-MD-M (body: $body)"
                            Log.w(TAG, msg)
                            errorLog.add(msg)
                            return@use
                        }

                        val headers = AnisetteHeaders(
                            serverUsed = server,
                            clientTime = json.optString("X-Apple-I-Client-Time", ""),
                            md = json.getString("X-Apple-I-MD"),
                            mdM = json.getString("X-Apple-I-MD-M"),
                            mdRinfo = json.optString("X-Apple-I-MD-RINFO", "17106176"),
                            mdLu = json.optString("X-Apple-I-MD-LU", ""),
                            srlNo = json.optString("X-Apple-I-SRL-NO", "0"),
                            clientInfo = json.optString("X-MMe-Client-Info", "<MacBookPro13,2> <macOS;13.1;22C65> <com.apple.AuthKit/1 (com.apple.akd/1.0)>"),
                            timeZone = json.optString("X-Apple-I-TimeZone", "UTC"),
                            locale = json.optString("X-Apple-Locale", "en_US"),
                            deviceId = json.optString("X-Mme-Device-Id", ""),
                            implementationVersion = implVersion
                        )

                        Log.i(TAG, "Successfully retrieved Anisette headers from $server in ${duration}ms ($implVersion)")
                        return@withContext Result.success(headers)
                    }
                } catch (e: Exception) {
                    val duration = System.currentTimeMillis() - startTime
                    val errDesc = "$server failed after ${duration}ms: ${e.javaClass.simpleName} - ${e.message}"
                    Log.w(TAG, errDesc)
                    errorLog.add(errDesc)
                }
            }

            val summaryError = "All anisette servers in fallback chain failed:\n" + errorLog.joinToString("\n")
            Log.e(TAG, summaryError)
            Result.failure(IOException(summaryError))
        }

    /**
     * Checks reachability and response latency of a single server.
     */
    suspend fun checkServer(serverUrl: String): ServerCheckResult = withContext(Dispatchers.IO) {
        val cleanUrl = serverUrl.trimEnd('/')
        val startTime = System.currentTimeMillis()
        try {
            val request = Request.Builder()
                .url("$cleanUrl/")
                .header("Accept", "application/json")
                .header("User-Agent", "iOS-Sideload-Bridge-Android/1.0")
                .get()
                .build()

            httpClient.newCall(request).execute().use { response ->
                val duration = System.currentTimeMillis() - startTime
                val implVersion = response.header("Implementation-Version")
                val code = response.code

                if (!response.isSuccessful) {
                    return@withContext ServerCheckResult(
                        serverUrl = cleanUrl,
                        isReachable = false,
                        statusCode = code,
                        responseTimeMs = duration,
                        implementationVersion = implVersion,
                        errorMessage = "HTTP error $code"
                    )
                }

                val body = response.body?.string() ?: ""
                val json = JSONObject(body)

                if (!json.has("X-Apple-I-MD") || !json.has("X-Apple-I-MD-M")) {
                    return@withContext ServerCheckResult(
                        serverUrl = cleanUrl,
                        isReachable = false,
                        statusCode = code,
                        responseTimeMs = duration,
                        implementationVersion = implVersion,
                        errorMessage = "Invalid JSON schema: missing X-Apple-I-MD headers"
                    )
                }

                val headers = AnisetteHeaders(
                    serverUsed = cleanUrl,
                    clientTime = json.optString("X-Apple-I-Client-Time", ""),
                    md = json.getString("X-Apple-I-MD"),
                    mdM = json.getString("X-Apple-I-MD-M"),
                    mdRinfo = json.optString("X-Apple-I-MD-RINFO", "17106176"),
                    mdLu = json.optString("X-Apple-I-MD-LU", ""),
                    srlNo = json.optString("X-Apple-I-SRL-NO", "0"),
                    clientInfo = json.optString("X-MMe-Client-Info", ""),
                    timeZone = json.optString("X-Apple-I-TimeZone", "UTC"),
                    locale = json.optString("X-Apple-Locale", "en_US"),
                    deviceId = json.optString("X-Mme-Device-Id", ""),
                    implementationVersion = implVersion
                )

                ServerCheckResult(
                    serverUrl = cleanUrl,
                    isReachable = true,
                    statusCode = code,
                    responseTimeMs = duration,
                    implementationVersion = implVersion,
                    headers = headers
                )
            }
        } catch (e: Exception) {
            val duration = System.currentTimeMillis() - startTime
            ServerCheckResult(
                serverUrl = cleanUrl,
                isReachable = false,
                statusCode = 0,
                responseTimeMs = duration,
                errorMessage = "${e.javaClass.simpleName}: ${e.message}"
            )
        }
    }

    /**
     * Checks reachability of all servers in the list.
     */
    suspend fun checkAllServers(servers: List<String> = OFFICIAL_SERVERS): List<ServerCheckResult> =
        withContext(Dispatchers.IO) {
            servers.map { checkServer(it) }
        }
}
